package org.apache.commons.math.ode.nonstiff;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.ode.ExpandableStatefulODE;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathIllegalStateException;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen5Test {

    private TestIntegrator integrator;
    private ExpandableStatefulODE mockEquations;
    private RungeKuttaStepInterpolator mockInterpolator;

    // Concrete implementation of the abstract class for testing
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        private double errorToReturn = 0.5;
        private int computeDerivativesCount = 0;
        private boolean shouldThrowInCompute = false;

        protected TestIntegrator(final String name, final boolean fsal, final double[] c, final double[][] a, 
                                 final double[] b, final RungeKuttaStepInterpolator prototype, 
                                 final double minStep, final double maxStep, 
                                 final double scalAbsoluteTolerance, final double scalRelativeTolerance) {
            super(name, fsal, c, a, b, prototype, minStep, maxStep, scalAbsoluteTolerance, scalRelativeTolerance);
        }

        @Override
        public int getOrder() {
            return 2;
        }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return errorToReturn;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            computeDerivativesCount++;
            if (shouldThrowInCompute) {
                throw new MathIllegalArgumentException("Simulated error");
            }
            for (int i = 0; i < y.length; i++) {
                yDot[i] = y[i]; // dy/dt = y
            }
        }

        // Mocking protected methods used in the loop
        @Override
        protected double initializeStep(double forward, int order, double[] scale, double t, double[] y, double[] yDotK0, double[] yDotK1) {
            return 0.1;
        }

        @Override
        protected double filterStep(double h, boolean forward, boolean isLast) {
            return h;
        }

        @Override
        protected double acceptStep(RungeKuttaStepInterpolator interpolator, double[] y, double[] yDot, double t) {
            // Return t if we want to end the loop immediately or progress
            return t - 0.05; 
        }
    }

    @Before
    public void setUp() {
        mockEquations = mock(ExpandableStatefulODE.class);
        mockInterpolator = mock(RungeKuttaStepInterpolator.class);

        // Default setup for coefficients (simple Butcher tableau)
        double[] c = {0.5, 1.0};
        double[][] a = {{0, 0}, {0.5, 0}};
        double[] b = {0.5, 0.5};

        // Mocking prototype.copy() behavior via a specialized setup if needed, 
        // but here we'll use a real-ish instance or a spy.
        integrator = new TestIntegrator("Test", true, c, a, b, mockInterpolator, 1e-10, 1.0, 1e-6, 1e-6);

        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});
        when(mockEquations.getTime()).thenReturn(0.0);
    }

    @Test
    public void testIntegrate_SuccessForward() throws Exception {
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});

        // Setup to finish in one step
        integrator.errorToReturn = 0.1; 

        // Mocking the behavior where acceptStep makes isLastStep true
        // Since we can't easily override isLastStep (it's a field), 
        // we rely on the logic: if acceptStep returns t, the loop should end.
        // However, the code uses 'isLastStep' which is set by acceptStep.
        // We need to mock the behavior of the integrator to satisfy the loop.

        // We'll use a spy to control isLastStep or simulate the flow
        TestIntegrator spyIntegrator = spy(integrator);
        doReturn(true).when(spyIntegrator).acceptStep(any(), any(), any(), anyDouble());
        // We need to force isLastStep to true via the internal logic. 
        // The method 'acceptStep' is what sets isLastStep in the real code.
        // Since we can't change the source, we simulate the state via the equation's return.

        // For the sake of this test, let's assume a simple successful integration
        // where the loop runs once.
        mockEquations.setTime(0.1); // This is set at the end

        // Because we cannot easily control the private/protected 'isLastStep' without 
        // a real implementation, we test the logic flow.

        // Testing a simple case where error is low (0.1 < 1.0)
        integrator.integrate(mockEquations, 0.1);

        verify(mockEquations, atLeastOnce()).getCompleteState();
        verify(mockEquations, atLeastOnce()).setTime(anyDouble());
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testIntegrate_SanityCheckFailure() throws Exception {
        // If sanityChecks throws, integrate should throw
        // Since sanityChecks is likely private/protected and calls on equations
        when(mockEquations.getTime()).thenThrow(new MathIllegalArgumentException("Invalid time"));
        integrator.integrate(mockEquations, 0.1);
    }

    @Test
    public void testIntegrate_StepRejection() throws Exception {
        // Force error >= 1.0 to trigger the 'while (error >= 1.0)' loop
        integrator.errorToReturn = 2.0;

        // We need to make sure the loop eventually terminates.
        // We can do this by making error < 1.0 after one iteration.
        TestIntegrator adaptiveIntegrator = new TestIntegrator("Adaptive", true, 
            new double[]{0.5, 1.0}, new double[][]{{0,0},{0.5,0}}, new double[]{0.5, 0.5}, 
            mockInterpolator, 1e-10, 1.0, 1e-6, 1e-6) {
            private int count = 0;
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                count++;
                return (count == 1) ? 2.0 : 0.1; // Reject first, accept second
            }
        };

        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});

        adaptiveIntegrator.integrate(mockEquations, 0.1);

        verify(mockEquations, atLeastOnce()).getCompleteState();
    }

    @Test
    public void testIntegrate_NoFSAL() throws Exception {
        // Create integrator with fsal = false
        double[] c = {0.5, 1.0};
        double[][] a = {{0, 0}, {0.5, 0}};
        double[] b = {0.5, 0.5};
        TestIntegrator noFsalIntegrator = new TestIntegrator("NoFSAL", false, c, a, b, mockInterpolator, 1e-10, 1.0, 1e-6, 1e-6);

        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});
        noFsalIntegrator.errorToReturn = 0.1;

        noFsalIntegrator.integrate(mockEquations, 0.1);

        // With fsal=false, computeDerivatives is called at the start of every step
        assertTrue(noFsalIntegrator.computeDerivativesCount >= 1);
    }

    @Test
    public void testIntegrate_VectorTolerance() throws Exception {
        // Test the branch where vecAbsoluteTolerance is not null
        double[] absTol = {1e-6, 1e-6};
        double[] relTol = {1e-6, 1e-6};

        TestIntegrator vecIntegrator = new TestIntegrator("VecTol", true, 
            new double[]{0.5, 1.0}, new double[][]{{0,0},{0.5,0}}, new double[]{0.5, 0.5}, 
            mockInterpolator, 1e-10, 1.0, absTol, relTol);

        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0, 1.0});
        vecIntegrator.errorToReturn = 0.1;

        vecIntegrator.integrate(mockEquations, 0.1);

        verify(mockEquations, atLeastOnce()).getCompleteState();
    }
}
